/* eslint-disable no-undef */
import english from '../en';
import spanish from '../es';

const englishKeyArray = Object.keys(english).sort();
const spanishKeyArray = Object.keys(spanish).sort();

describe('Translation Objects', () => {
  test('english and spanish translation objects should have the same number of keys', () => {
    const englishKeyCount = englishKeyArray.length;
    const spanishKeyCount = spanishKeyArray.length;
    expect(englishKeyCount === spanishKeyCount).toBe(true);
  });

  test('english and spanish traslations keys should equal', () => {
    expect(englishKeyArray).toEqual(spanishKeyArray);
  });
});
